input.command:
cat > package.json <<'EOF'
{
  "name": "shadow-blade-awakening",
  "private": true,
  "version": "1.0.0",
  "type": "module",
  "scripts": {
    "dev": "vite --host 0.0.0.0 --port 3000",
    "build": "vite build",
    "preview": "vite preview --host 0.0.0.0 --port 3000"
  },
  "dependencies": {
    "three": "0.180.0"
  },
  "devDependencies": {
    "vite": "7.1.7"
  }
}
EOF
npm install --no-audit --no-fund

input.content:
@charset "UTF-8";

:root {
  --ink: #06070d;
  --ink-2: #0c0e19;
  --panel: rgba(9, 11, 22, 0.78);
  --panel-line: rgba(155, 142, 255, 0.28);
  --text: #f3f0ff;
  --muted: #9b9ab4;
  --violet: #9b7bff;
  --violet-hot: #c4a8ff;
  --cyan: #74e7ff;
  --ember: #ff7a42;
  --gold: #f4cc7b;
  --blood: #ff436b;
  --safe-top: max(18px, env(safe-area-inset-top));
  --safe-bottom: max(18px, env(safe-area-inset-bottom));
  --display: "Arial Black", "Pretendard", "Noto Sans KR", "Malgun Gothic", system-ui, sans-serif;
  --sans: "Pretendard", "Noto Sans KR", "Apple SD Gothic Neo", "Malgun Gothic", system-ui, -apple-system, sans-serif;
}

* { box-sizing: border-box; }
html, body { width: 100%; height: 100%; margin: 0; overflow: hidden; background: var(--ink); }
body {
  color: var(--text);
  font-family: var(--sans);
  -webkit-font-smoothing: antialiased;
  user-select: none;
  overscroll-behavior: none;
}
button { font: inherit; color: inherit; border: 0; background: none; cursor: pointer; -webkit-tap-highlight-color: transparent; }
kbd {
  display: inline-flex; align-items: center; justify-content: center;
  min-width: 26px; height: 20px; padding: 0 6px;
  border: 1px solid rgba(255,255,255,.18); border-bottom-color: rgba(255,255,255,.3);
  border-radius: 4px; background: rgba(255,255,255,.06);
  font-family: var(--sans); font-size: 10px; font-weight: 700; letter-spacing: .04em; color: #d9d6ef;
}
.hidden { display: none !important; }
#app { position: relative; width: 100%; height: 100%; isolation: isolate; background: #05060d; }
#game-canvas { position: absolute; inset: 0; width: 100%; height: 100%; display: block; outline: none; }
.screen-vignette {
  position: absolute; inset: 0; z-index: 2; pointer-events: none;
  background:
    radial-gradient(ellipse at 50% 42%, transparent 42%, rgba(3,4,10,.36) 100%),
    linear-gradient(180deg, rgba(2,3,8,.44), transparent 15%, transparent 78%, rgba(2,3,8,.62));
}
.screen-grain {
  position: absolute; inset: 0; z-index: 3; pointer-events: none; opacity: .15; mix-blend-mode: soft-light;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.45'/%3E%3C/svg%3E");
  animation: grainShift .35s steps(2) infinite;
}
@keyframes grainShift { 0%{transform:translate(0,0)} 25%{transform:translate(-2%,1%)} 50%{transform:translate(1%,-2%)} 75%{transform:translate(2%,2%)} 100%{transform:translate(0,0)} }
.cinema-bars { position: absolute; inset: 0; z-index: 4; pointer-events: none; }
.cinema-bars i { position: absolute; left: 0; right: 0; height: 0; background: #020207; transition: height 1.1s cubic-bezier(.2,.8,.2,1); }
.cinema-bars i:first-child { top: 0; }
.cinema-bars i:last-child { bottom: 0; }
body.cinematic .cinema-bars i { height: 7.2vh; }

/* ---------- LOADING ---------- */
.loading-screen {
  position: absolute; inset: 0; z-index: 80; display: flex; flex-direction: column;
  align-items: center; justify-content: center; background:
    radial-gradient(circle at 50% 48%, rgba(58,35,112,.35), transparent 35%),
    #05060c; transition: opacity .7s ease, visibility .7s;
}
.loading-screen.out { opacity: 0; visibility: hidden; }
.loading-sigil { position: relative; width: 110px; height: 110px; margin-bottom: 28px; }
.loading-sigil::before, .loading-sigil::after, .loading-sigil span {
  content: ""; position: absolute; inset: 0; border: 1px solid rgba(159,125,255,.5); transform: rotate(45deg);
}
.loading-sigil::after { inset: 12px; border-color: rgba(116,231,255,.28); animation: sigilSpin 5s linear infinite; }
.loading-sigil span { inset: 28px; background: radial-gradient(circle, #d7c8ff 0 5%, #7c4dff 10%, transparent 65%); border: 0; animation: sigilPulse 1.8s ease-in-out infinite; }
@keyframes sigilSpin { to { transform: rotate(405deg); } }
@keyframes sigilPulse { 50% { transform: rotate(45deg) scale(1.18); opacity: .7; } }
.loading-title { font-family: var(--display); font-size: 24px; letter-spacing: .28em; text-indent: .28em; }
.loading-sub { margin-top: 8px; font-size: 9px; letter-spacing: .44em; color: var(--muted); }
.loading-track { width: min(320px, 62vw); height: 2px; margin-top: 34px; background: rgba(255,255,255,.1); overflow: hidden; }
.loading-track i { display: block; width: 4%; height: 100%; background: linear-gradient(90deg, var(--violet), var(--cyan)); box-shadow: 0 0 12px var(--violet); transition: width .4s ease; }
.loading-copy { margin-top: 13px; color: #7d7b94; font-size: 10px; letter-spacing: .14em; }

/* ---------- START ---------- */
.start-screen { position: absolute; inset: 0; z-index: 30; overflow: hidden; background: linear-gradient(90deg, rgba(4,5,12,.95) 0%, rgba(4,5,12,.82) 34%, rgba(4,5,12,.18) 68%, rgba(4,5,12,.5) 100%); }
.start-screen::after {
  content: ""; position: absolute; inset: 0; pointer-events: none;
  background: linear-gradient(180deg, rgba(4,5,12,.55), transparent 20%, transparent 72%, rgba(4,5,12,.75));
}
.start-halo { position: absolute; width: 58vw; height: 58vw; left: 49%; top: 46%; transform: translate(-50%,-50%); border-radius: 50%; background: radial-gradient(circle, rgba(126,83,255,.12), transparent 65%); filter: blur(20px); }
.start-grid { position: absolute; inset: 0; opacity: .22; background-image: linear-gradient(rgba(126,96,255,.15) 1px, transparent 1px), linear-gradient(90deg, rgba(126,96,255,.15) 1px, transparent 1px); background-size: 74px 74px; mask-image: radial-gradient(ellipse at 64% 48%, black, transparent 67%); transform: perspective(500px) rotateX(58deg) translateY(35%) scale(1.7); transform-origin: 60% 100%; }
.start-copy { position: relative; z-index: 2; width: min(760px, 53vw); padding-left: clamp(42px, 7vw, 112px); padding-top: 16vh; }
.eyebrow { display: flex; align-items: center; gap: 11px; color: #aaa4c8; font-size: 10px; font-weight: 700; letter-spacing: .24em; }
.eyebrow i { width: 34px; height: 1px; background: var(--violet); box-shadow: 0 0 8px var(--violet); }
.eyebrow span { color: var(--gold); border: 1px solid rgba(244,204,123,.35); border-radius: 2px; padding: 3px 6px; letter-spacing: .12em; }
.title-lockup { margin-top: 18px; }
.hangul-title { font-family: var(--display); font-size: clamp(76px, 8.2vw, 148px); line-height: .82; letter-spacing: -.075em; filter: drop-shadow(0 10px 34px rgba(110,58,255,.28)); }
.hangul-title span { display: block; color: #fff; }
.hangul-title b { display: block; color: transparent; -webkit-text-stroke: 1.5px rgba(200,181,255,.8); margin-left: .42em; letter-spacing: -.04em; }
.eng-title { margin-top: 15px; font-family: var(--display); font-size: clamp(24px, 3vw, 45px); letter-spacing: .18em; color: #d8d1f4; }
.eng-title em { font-style: normal; color: var(--ember); text-shadow: 0 0 26px rgba(255,106,58,.55); }
.title-rule { display: flex; align-items: center; gap: 13px; margin-top: 13px; color: var(--gold); font-size: 9px; letter-spacing: .54em; }
.title-rule i { width: 48px; height: 1px; background: linear-gradient(90deg, transparent, rgba(244,204,123,.7)); }
.title-rule i:last-child { background: linear-gradient(90deg, rgba(244,204,123,.7), transparent); }
.start-blurb { margin: 27px 0 0; color: #b9b6cb; font-size: clamp(13px, 1.1vw, 16px); line-height: 1.8; letter-spacing: -.01em; }
.start-blurb strong { color: var(--violet-hot); font-weight: 700; }
.start-actions { display: flex; align-items: center; gap: 12px; margin-top: 31px; }
.primary-btn {
  position: relative; overflow: hidden; display: inline-flex; align-items: center; gap: 20px;
  height: 58px; padding: 0 18px 0 27px; background: linear-gradient(105deg, #8e62ff, #5f39da 65%, #472a9f);
  border: 1px solid rgba(211,195,255,.52); box-shadow: 0 9px 34px rgba(101,60,220,.4), inset 0 1px rgba(255,255,255,.2);
  clip-path: polygon(0 0, calc(100% - 13px) 0, 100% 13px, 100% 100%, 13px 100%, 0 calc(100% - 13px));
  transition: transform .18s ease, filter .18s ease;
}
.primary-btn:hover { transform: translateY(-2px); filter: brightness(1.13); }
.primary-btn:active { transform: translateY(0) scale(.99); }
.primary-btn span { font-size: 15px; font-weight: 800; letter-spacing: .02em; }
.primary-btn kbd { height: 24px; background: rgba(0,0,0,.22); border-color: rgba(255,255,255,.2); }
.primary-btn .btn-shine { position: absolute; inset: 0; transform: translateX(-120%); background: linear-gradient(90deg, transparent, rgba(255,255,255,.25), transparent); animation: btnShine 4.2s ease-in-out infinite; }
@keyframes btnShine { 0%,58% { transform: translateX(-120%); } 82%,100% { transform: translateX(130%); } }
.ghost-btn { height: 54px; padding: 0 21px; border: 1px solid rgba(255,255,255,.17); background: rgba(255,255,255,.035); color: #c9c5dd; font-size: 12px; font-weight: 700; letter-spacing: .08em; backdrop-filter: blur(10px); transition: background .2s, border-color .2s; }
.ghost-btn:hover { background: rgba(255,255,255,.08); border-color: rgba(255,255,255,.33); }
.start-features { display: flex; gap: 1px; margin-top: 33px; width: fit-content; background: rgba(255,255,255,.09); border: 1px solid rgba(255,255,255,.08); }
.start-features div { min-width: 103px; padding: 12px 17px; background: rgba(7,8,16,.6); backdrop-filter: blur(8px); }
.start-features b { display: block; font-family: var(--display); font-size: 21px; color: var(--violet-hot); letter-spacing: .04em; }
.start-features span { display: block; margin-top: 4px; color: #7f7c96; font-size: 9px; letter-spacing: .13em; }
.start-foot { display: flex; align-items: center; gap: 9px; margin-top: 27px; color: #68667f; font-size: 10px; letter-spacing: .04em; }
.online-dot { width: 6px; height: 6px; border-radius: 50%; background: #64f0bd; box-shadow: 0 0 10px #64f0bd; animation: onlinePulse 2s ease-in-out infinite; }
@keyframes onlinePulse { 50% { opacity: .35; } }
.start-side { position: absolute; right: 3.2vw; top: 13vh; z-index: 2; display: flex; flex-direction: column; align-items: flex-end; gap: 15px; opacity: .75; }
.side-line { width: 1px; height: 130px; background: linear-gradient(transparent, rgba(196,168,255,.6)); }
.side-word { writing-mode: vertical-rl; font-family: var(--display); font-size: 62px; letter-spacing: .24em; color: transparent; -webkit-text-stroke: 1px rgba(196,168,255,.24); }
.side-small { writing-mode: vertical-rl; font-size: 8px; letter-spacing: .38em; color: #8f86b5; line-height: 1.7; text-align: right; }

/* ---------- HUD ---------- */
.hud { position: absolute; inset: 0; z-index: 10; pointer-events: none; }
.hud button { pointer-events: auto; }
.hud-top { display: flex; justify-content: space-between; align-items: flex-start; padding: var(--safe-top) clamp(16px, 2.1vw, 38px) 0; gap: 18px; }
.hunter-card { display: flex; align-items: stretch; width: 330px; min-height: 89px; background: linear-gradient(110deg, rgba(8,10,21,.92), rgba(13,15,29,.67)); border: 1px solid rgba(159,139,255,.26); border-left: 2px solid var(--violet); box-shadow: 0 12px 32px rgba(0,0,0,.35), inset 0 1px rgba(255,255,255,.06); clip-path: polygon(0 0, 100% 0, 100% calc(100% - 13px), calc(100% - 13px) 100%, 0 100%); backdrop-filter: blur(12px); }
.level-orb { position: relative; flex: 0 0 74px; display: flex; flex-direction: column; align-items: center; justify-content: center; border-right: 1px solid rgba(255,255,255,.09); background: radial-gradient(circle, rgba(128,88,255,.23), transparent 70%); }
.level-orb::after { content: ""; position: absolute; width: 48px; height: 48px; border: 1px solid rgba(155,123,255,.4); transform: rotate(45deg); box-shadow: 0 0 18px rgba(155,123,255,.13); }
.level-orb span { position: relative; z-index: 1; font-size: 7px; letter-spacing: .26em; color: #9c91cb; }
.level-orb b { position: relative; z-index: 1; font-family: var(--display); font-size: 24px; line-height: 1; color: #fff; text-shadow: 0 0 16px var(--violet); }
.hunter-body { flex: 1; padding: 10px 13px 9px; min-width: 0; }
.hunter-name { display: flex; align-items: center; gap: 7px; margin-bottom: 6px; }
.hunter-name b { font-size: 13px; letter-spacing: -.02em; }
.hunter-name span { padding: 2px 5px; border: 1px solid rgba(244,204,123,.35); color: var(--gold); font-size: 8px; font-weight: 700; letter-spacing: .06em; }
.live-pip { width: 5px; height: 5px; margin-left: auto; border-radius: 50%; background: #6bf5c3; box-shadow: 0 0 7px #6bf5c3; }
.stat-bar { position: relative; height: 11px; margin-top: 4px; background: rgba(0,0,0,.5); border: 1px solid rgba(255,255,255,.09); overflow: hidden; }
.stat-bar i { display: block; height: 100%; width: 100%; transition: width .22s ease; }
.hp-bar i { background: linear-gradient(90deg, #c42955, #ff5674); box-shadow: 0 0 12px rgba(255,67,107,.55); }
.mp-bar i { background: linear-gradient(90deg, #4b46ce, #74c6ff); box-shadow: 0 0 12px rgba(116,198,255,.45); }
.stat-bar span { position: absolute; right: 4px; top: 0; height: 100%; display: flex; align-items: center; font-size: 7px; font-weight: 700; letter-spacing: .04em; text-shadow: 0 1px 2px #000; }
.stat-bar b { position: absolute; left: 5px; top: 0; height: 100%; display: flex; align-items: center; font-size: 6px; letter-spacing: .14em; color: rgba(255,255,255,.75); }
.xp-row { display: flex; align-items: center; gap: 6px; margin-top: 5px; }
.xp-row > span { font-size: 6px; letter-spacing: .16em; color: #7b7596; }
.xp-bar { flex: 1; height: 2px; background: rgba(255,255,255,.1); }
.xp-bar i { display: block; width: 0; height: 100%; background: linear-gradient(90deg, #6c50ff, #d3bcff); box-shadow: 0 0 7px #8c68ff; transition: width .3s ease; }
.xp-row > b { font-size: 7px; color: #8e88a8; font-weight: 500; }
.quest-card { width: min(370px, 29vw); padding: 10px 15px 11px; background: linear-gradient(180deg, rgba(10,12,23,.8), rgba(9,10,20,.5)); border-top: 1px solid rgba(244,204,123,.36); border-bottom: 1px solid rgba(255,255,255,.06); box-shadow: 0 12px 32px rgba(0,0,0,.25); backdrop-filter: blur(10px); clip-path: polygon(8px 0, 100% 0, 100% calc(100% - 8px), calc(100% - 8px) 100%, 0 100%, 0 8px); }
.quest-kicker { display: flex; align-items: center; gap: 6px; color: #9b8fbf; font-size: 7px; font-weight: 700; letter-spacing: .18em; }
.quest-kicker .quest-icon { color: var(--gold); font-size: 9px; }
.quest-kicker em { margin-left: auto; font-style: normal; color: var(--gold); letter-spacing: .12em; }
.quest-name { margin-top: 5px; font-size: 11px; font-weight: 700; color: #e7e3f5; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.quest-progress { height: 2px; margin-top: 8px; background: rgba(255,255,255,.09); }
.quest-progress i { display: block; width: 0%; height: 100%; background: linear-gradient(90deg, var(--gold), #ff9a5c); box-shadow: 0 0 8px rgba(244,204,123,.6); transition: width .4s ease; }
.quest-sub { display: flex; align-items: center; gap: 5px; margin-top: 5px; color: #706c88; font-size: 7px; letter-spacing: .06em; }
.quest-sub b { color: #c8c2e3; font-size: 8px; }
.quest-sub b:last-child { margin-left: auto; color: var(--gold); }
.radar-card { width: 128px; }
.radar-label { display: flex; justify-content: space-between; margin-bottom: 6px; color: #77718f; font-size: 7px; letter-spacing: .12em; }
.radar-label b { color: var(--cyan); font-weight: 600; }
.radar-disc { position: relative; width: 112px; height: 112px; margin-left: auto; border-radius: 50%; border: 1px solid rgba(116,231,255,.24); background: radial-gradient(circle, rgba(21,39,58,.6), rgba(6,8,16,.65) 72%); box-shadow: 0 0 25px rgba(0,0,0,.4), inset 0 0 30px rgba(55,130,180,.08); overflow: hidden; }
#radar { width: 100%; height: 100%; opacity: .95; }
.radar-ring { position: absolute; inset: 18%; border: 1px solid rgba(116,231,255,.11); border-radius: 50%; }
.radar-ring::after { content: ""; position: absolute; inset: 32%; border: 1px solid rgba(116,231,255,.1); border-radius: 50%; }
.radar-sweep { position: absolute; inset: 0; border-radius: 50%; background: conic-gradient(from 0deg, transparent 0 300deg, rgba(116,231,255,.22) 350deg, transparent 360deg); animation: radarSpin 4s linear infinite; }
@keyframes radarSpin { to { transform: rotate(360deg); } }
.radar-self { position: absolute; left: 50%; top: 50%; width: 5px; height: 5px; border-radius: 50%; background: #fff; box-shadow: 0 0 9px var(--cyan); transform: translate(-50%,-50%); }

.wave-banner { position: absolute; left: 50%; top: 16%; transform: translate(-50%,-12px); text-align: center; opacity: 0; transition: opacity .35s, transform .5s; pointer-events: none; }
.wave-banner.show { opacity: 1; transform: translate(-50%,0); }
.banner-kicker { color: var(--gold); font-size: 8px; font-weight: 700; letter-spacing: .44em; text-indent: .44em; }
.banner-title { margin-top: 3px; font-family: var(--display); font-size: clamp(34px, 4vw, 58px); line-height: 1; letter-spacing: .08em; color: #fff; text-shadow: 0 0 32px rgba(137,98,255,.65), 0 2px 0 rgba(0,0,0,.4); }
.banner-sub { margin-top: 8px; color: #aaa2c9; font-size: 10px; letter-spacing: .1em; }
.boss-wrap { position: absolute; left: 50%; top: 10.5%; width: min(630px, 58vw); transform: translateX(-50%); }
.boss-head { display: flex; align-items: flex-end; gap: 9px; margin-bottom: 5px; }
.boss-head span { color: var(--blood); font-size: 7px; letter-spacing: .22em; }
.boss-head b { font-size: 14px; letter-spacing: .03em; text-shadow: 0 2px 8px #000; }
.boss-head em { margin-left: auto; color: #ff9ba9; font-size: 7px; font-style: normal; letter-spacing: .16em; }
.boss-track { position: relative; height: 8px; background: rgba(0,0,0,.6); border: 1px solid rgba(255,67,107,.3); transform: skewX(-18deg); overflow: hidden; }
.boss-track i { display: block; height: 100%; width: 100%; background: linear-gradient(90deg, #72152d, #ff3f63 55%, #ff9a74); box-shadow: 0 0 16px rgba(255,67,107,.55); transition: width .25s ease; }
.boss-track span { position: absolute; inset: 0; background: repeating-linear-gradient(90deg, transparent 0 12%, rgba(0,0,0,.26) 12% 12.4%); }

.combo-wrap { position: absolute; right: clamp(25px, 4vw, 70px); top: 33%; text-align: right; opacity: 0; transform: translateX(14px); transition: opacity .2s, transform .2s; }
.combo-wrap.show { opacity: 1; transform: translateX(0); }
.combo-num { font-family: var(--display); font-size: 52px; line-height: .85; color: #fff; text-shadow: 0 0 26px rgba(185,142,255,.65); }
.combo-label { margin-top: 3px; color: var(--violet-hot); font-size: 7px; font-weight: 700; letter-spacing: .26em; }
.combo-grade { margin-top: 2px; color: var(--gold); font-size: 9px; font-weight: 700; letter-spacing: .16em; }
.toast { position: absolute; left: 50%; top: 25%; transform: translate(-50%,-8px); padding: 9px 19px; background: rgba(8,9,18,.76); border: 1px solid rgba(155,123,255,.24); color: #d8d1f2; font-size: 11px; letter-spacing: .03em; opacity: 0; transition: opacity .25s, transform .25s; backdrop-filter: blur(10px); white-space: nowrap; }
.toast.show { opacity: 1; transform: translate(-50%,0); }
.toast.gold { border-color: rgba(244,204,123,.4); color: var(--gold); }
.damage-layer { position: absolute; inset: 0; overflow: hidden; }
.dmg { position: absolute; transform: translate(-50%,-50%); font-family: var(--display); font-size: 15px; color: #fff; text-shadow: 0 2px 5px #000, 0 0 13px rgba(168,119,255,.7); pointer-events: none; animation: dmgFloat .75s cubic-bezier(.1,.8,.3,1) forwards; will-change: transform, opacity; }
.dmg.crit { color: #ffd37b; font-size: 22px; text-shadow: 0 2px 5px #000, 0 0 16px rgba(255,160,70,.9); }
.dmg.player { color: #ff718a; font-size: 17px; }
.dmg.heal { color: #7dffc5; }
@keyframes dmgFloat { 0% { opacity: 0; transform: translate(-50%,-30%) scale(.7); } 18% { opacity: 1; transform: translate(-50%,-60%) scale(1.12); } 100% { opacity: 0; transform: translate(-50%,-190%) scale(.92); } }

.hud-bottom { position: absolute; left: 0; right: 0; bottom: var(--safe-bottom); display: flex; align-items: flex-end; justify-content: space-between; padding: 0 clamp(16px, 2.1vw, 38px); gap: 20px; }
.control-hint { display: flex; gap: 15px; width: 330px; padding-bottom: 6px; opacity: .74; }
.control-hint div { display: flex; align-items: center; gap: 5px; }
.control-hint span { color: #8d89a2; font-size: 8px; white-space: nowrap; }
.control-hint kbd { height: 17px; min-width: 20px; font-size: 7px; }
.ability-dock { display: flex; align-items: flex-end; gap: 7px; pointer-events: auto; }
.ability { position: relative; width: 78px; height: 72px; padding: 9px 4px 6px; background: linear-gradient(180deg, rgba(24,25,47,.9), rgba(8,9,17,.88)); border: 1px solid rgba(155,123,255,.25); box-shadow: 0 9px 24px rgba(0,0,0,.32), inset 0 1px rgba(255,255,255,.06); clip-path: polygon(8px 0, 100% 0, 100% calc(100% - 8px), calc(100% - 8px) 100%, 0 100%, 0 8px); transition: transform .12s, border-color .2s, background .2s; overflow: hidden; }
.ability:hover { transform: translateY(-3px); border-color: rgba(196,168,255,.6); background: linear-gradient(180deg, rgba(42,36,76,.92), rgba(13,12,25,.9)); }
.ability:active { transform: translateY(-1px) scale(.97); }
