    const hide = darkEnemyMat(0x231b2a, 0x2a0719, 0.24);
    const dark = darkEnemyMat(0x120e16, 0x160312, 0.18);
    const bodyMesh = box(1.25, 0.72, 1.85, hide, 0, 1.15, 0);
