export function animateShadow(rig, dt, opts = {}) {
  if (!rig) return;
  rig.time += dt;
  const cycle = rig.time * (3 + (opts.speed || 0));
  const walk = Math.min(1, (opts.speed || 0) / 4);
  rig.body.position.y = Math.abs(Math.sin(cycle)) * 0.05 * walk;
  rig.leftLeg.rotation.x = Math.sin(cycle) * 0.55 * walk;
  rig.rightLeg.rotation.x = -Math.sin(cycle) * 0.55 * walk;
  rig.leftArm.rotation.x = -Math.sin(cycle) * 0.35 * walk;
  rig.rightArm.rotation.x = Math.sin(cycle) * 0.25 * walk;
  if (opts.attack) {
    const p = Math.min(1, opts.attack.t / opts.attack.dur);
    const s = Math.sin(p * Math.PI);
    rig.rightArm.rotation.x = -0.2 - s * 2.3;
    rig.rightArm.rotation.z = s * 0.4;
    rig.body.rotation.y = s * 0.5;
  } else {
    rig.body.rotation.y *= 0.86;
  }
  rig.aura.rotation.z += dt * 1.5;
  rig.aura.material.opacity = 0.3 + Math.sin(rig.time * 3) * 0.12;
}

export { makeSword, addGlowEyes, glowMaterial };

import * as THREE from 'three';

const MAX_PARTICLES = 900;

const particleVert = /* glsl */`
  attribute float aSize;
  attribute float aAlpha;
  attribute vec3 aColor;
  varying vec3 vColor;
  varying float vAlpha;
  void main() {
    vColor = aColor;
    vAlpha = aAlpha;
    vec4 mv = modelViewMatrix * vec4(position, 1.0);
    gl_PointSize = aSize * (420.0 / max(1.0, -mv.z));
    gl_Position = projectionMatrix * mv;
  }
`;

const particleFrag = /* glsl */`
  varying vec3 vColor;
  varying float vAlpha;
  void main() {
    vec2 p = gl_PointCoord - 0.5;
    float d = length(p);
    float core = smoothstep(0.5, 0.0, d);
    float spark = smoothstep(0.16, 0.0, d);
    float a = core * 0.55 + spark * 0.9;
    if (a < 0.01) discard;
    gl_FragColor = vec4(vColor * (0.7 + spark * 1.4), a * vAlpha);
  }
`;

class ParticlePool {
  constructor(scene) {
    this.scene = scene;
    this.particles = [];
    const geo = new THREE.BufferGeometry();
    this.pos = new Float32Array(MAX_PARTICLES * 3);
    this.col = new Float32Array(MAX_PARTICLES * 3);
    this.size = new Float32Array(MAX_PARTICLES);
    this.alpha = new Float32Array(MAX_PARTICLES);
    geo.setAttribute('position', new THREE.BufferAttribute(this.pos, 3));
    geo.setAttribute('aColor', new THREE.BufferAttribute(this.col, 3));
    geo.setAttribute('aSize', new THREE.BufferAttribute(this.size, 1));
    geo.setAttribute('aAlpha', new THREE.BufferAttribute(this.alpha, 1));
    this.geo = geo;
    this.material = new THREE.ShaderMaterial({
      vertexShader: particleVert,
      fragmentShader: particleFrag,
      transparent: true,
      depthWrite: false,
      blending: THREE.AdditiveBlending,
    });
    this.points = new THREE.Points(geo, this.material);
    this.points.frustumCulled = false;
    this.points.renderOrder = 5;
    scene.add(this.points);
  }

  spawn(position, color, count, opts = {}) {
    const c = new THREE.Color(color);
    const speed = opts.speed ?? 4;
    const size = opts.size ?? 0.16;
    const life = opts.life ?? 0.65;
    const gravity = opts.gravity ?? 7;
    const spread = opts.spread ?? 1;
    const dir = opts.direction || null;
    const up = opts.up ?? 0.6;
    for (let i = 0; i < count; i++) {
      if (this.particles.length >= MAX_PARTICLES) this.particles.shift();
      const angle = Math.random() * Math.PI * 2;
      const radial = Math.random() * spread;
      let vx = Math.cos(angle) * radial * speed;
      let vz = Math.sin(angle) * radial * speed;
      let vy = (Math.random() * 0.8 + up) * speed;
      if (dir) {
        vx += dir.x * speed * (0.4 + Math.random() * 0.8);
        vy += dir.y * speed * 0.5;
        vz += dir.z * speed * (0.4 + Math.random() * 0.8);
      }
      const p = {
        pos: position.clone().add(new THREE.Vector3((Math.random() - 0.5) * 0.4, (Math.random() - 0.5) * 0.4, (Math.random() - 0.5) * 0.4)),
        vel: new THREE.Vector3(vx, vy, vz),
        color: c.clone().offsetHSL((Math.random() - 0.5) * 0.06, 0, (Math.random() - 0.5) * 0.15),
        size: size * (0.6 + Math.random() * 0.9),
        life: life * (0.6 + Math.random() * 0.7),
        maxLife: life,
        gravity,
        drag: opts.drag ?? 0.96,
      };
      this.particles.push(p);
    }
  }

  update(dt) {
    const n = this.particles.length;
    for (let i = n - 1; i >= 0; i--) {
      const p = this.particles[i];
      p.life -= dt;
      if (p.life <= 0) {
        this.particles.splice(i, 1);
        continue;
      }
      p.vel.y -= p.gravity * dt;
      p.vel.multiplyScalar(Math.pow(p.drag, dt * 60));
      p.pos.addScaledVector(p.vel, dt);
      if (p.pos.y < 0.05) {
        p.pos.y = 0.05;
        p.vel.y *= -0.22;
        p.vel.x *= 0.7;
        p.vel.z *= 0.7;
      }
    }
    for (let i = 0; i < MAX_PARTICLES; i++) {
      const p = this.particles[i];
      if (p) {
        const a = Math.max(0, p.life / p.maxLife);
        this.pos[i * 3] = p.pos.x;
        this.pos[i * 3 + 1] = p.pos.y;
        this.pos[i * 3 + 2] = p.pos.z;
        this.col[i * 3] = p.color.r;
        this.col[i * 3 + 1] = p.color.g;
        this.col[i * 3 + 2] = p.color.b;
        this.size[i] = p.size * (0.55 + a * 0.7);
        this.alpha[i] = Math.min(1, a * 1.8);
      } else {
        this.size[i] = 0;
        this.alpha[i] = 0;
      }
    }
    this.geo.attributes.position.needsUpdate = true;
    this.geo.attributes.aColor.needsUpdate = true;
    this.geo.attributes.aSize.needsUpdate = true;
    this.geo.attributes.aAlpha.needsUpdate = true;
  }
}

class SwordTrail {
  constructor(scene) {
    this.scene = scene;
    this.max = 18;
    this.points = [];
    this.color = new THREE.Color(0x9d7bff);
    this.active = false;
    this.fade = 0;
    const geo = new THREE.BufferGeometry();
    const positions = new Float32Array(this.max * 2 * 3);
    const colors = new Float32Array(this.max * 2 * 3);
    const indices = [];
    for (let i = 0; i < this.max - 1; i++) {
      const a = i * 2;
      indices.push(a, a + 1, a + 2, a + 1, a + 3, a + 2);
    }
    geo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    geo.setAttribute('color', new THREE.BufferAttribute(colors, 3));
    geo.setIndex(indices);
    geo.setDrawRange(0, 0);
    this.geo = geo;
    this.material = new THREE.MeshBasicMaterial({
      vertexColors: true, transparent: true, opacity: 1, side: THREE.DoubleSide,
      blending: THREE.AdditiveBlending, depthWrite: false,
    });
    this.mesh = new THREE.Mesh(geo, this.material);
    this.mesh.frustumCulled = false;
    this.mesh.renderOrder = 4;
    scene.add(this.mesh);
  }

  start(color) {
    this.color.set(color);
    this.points.length = 0;
    this.active = true;
    this.fade = 1;
    this.material.opacity = 1;
  }

  push(base, tip) {
    if (!this.active) return;
    this.points.unshift({ base: base.clone(), tip: tip.clone() });
    if (this.points.length > this.max) this.points.pop();
  }

  end() {
    this.active = false;
  }

  update(dt) {
    if (!this.active) this.fade = Math.max(0, this.fade - dt * 3.8);
    else this.fade = Math.min(1, this.fade + dt * 8);
    const positions = this.geo.attributes.position.array;
    const colors = this.geo.attributes.color.array;
    const count = this.points.length;
    for (let i = 0; i < count; i++) {
      const p = this.points[i];
      const idx = i * 6;
      positions[idx] = p.base.x;
      positions[idx + 1] = p.base.y;
      positions[idx + 2] = p.base.z;
      positions[idx + 3] = p.tip.x;
      positions[idx + 4] = p.tip.y;
      positions[idx + 5] = p.tip.z;
      const a = Math.pow(1 - i / this.max, 1.7) * this.fade;
      const c = this.color;
      colors[idx] = c.r * a * 0.35;
      colors[idx + 1] = c.g * a * 0.35;
      colors[idx + 2] = c.b * a * 0.35;
      colors[idx + 3] = c.r * a;
      colors[idx + 4] = c.g * a;
      colors[idx + 5] = c.b * a;
    }
    this.geo.attributes.position.needsUpdate = true;
    this.geo.attributes.color.needsUpdate = true;
    this.geo.setDrawRange(0, Math.max(0, (count - 1) * 6));
    this.material.opacity = this.fade;
    this.mesh.visible = this.fade > 0.01 && count > 1;
    if (!this.active && this.fade <= 0.01) this.points.length = 0;
  }
}

export class Effects {
  constructor(scene, camera) {
    this.scene = scene;
    this.camera = camera;
    this.particles = new ParticlePool(scene);
    this.trail = new SwordTrail(scene);
    this.items = [];
    this.flashLights = [];
  }

  startTrail(color = 0x9d7bff) { this.trail.start(color); }
  pushTrail(base, tip) { this.trail.push(base, tip); }
  endTrail() { this.trail.end(); }

  burst(position, color = 0x9d7bff, count = 12, opts = {}) {
    this.particles.spawn(position, color, count, opts);
  }

  hitSpark(position, color = 0xd9c8ff) {
    this.particles.spawn(position, color, 14, { speed: 7, size: 0.13, life: 0.35, gravity: 12, up: 0.3 });
    this.particles.spawn(position, 0xffffff, 5, { speed: 9, size: 0.09, life: 0.18, gravity: 2, up: 0.4 });
  }

  bloodBurst(position, color = 0xff3e63) {
    this.particles.spawn(position, color, 16, { speed: 5.5, size: 0.15, life: 0.6, gravity: 14, up: 0.45 });
    this.particles.spawn(position, 0x3a0a22, 8, { speed: 3, size: 0.3, life: 0.8, gravity: 2, up: 0.7 });
  }

  soulBurst(position, color = 0xa67bff, count = 24) {
    this.particles.spawn(position, color, count, { speed: 3.8, size: 0.19, life: 1.2, gravity: -1.2, up: 0.9, drag: 0.93 });
    this.particles.spawn(position, 0xe8dbff, 6, { speed: 2.5, size: 0.24, life: 1.5, gravity: -2.5, up: 1.1, drag: 0.9 });
  }

  spawnRing(position, color = 0x9d7bff, opts = {}) {
    const geo = new THREE.RingGeometry(0.45, 0.64, 64);
    const material = new THREE.MeshBasicMaterial({
      color, transparent: true, opacity: opts.opacity ?? 0.85, side: THREE.DoubleSide,
      blending: THREE.AdditiveBlending, depthWrite: false,
    });
    const mesh = new THREE.Mesh(geo, material);
    mesh.rotation.x = -Math.PI / 2;
    mesh.position.copy(position);
    mesh.position.y = opts.y ?? 0.06;
    mesh.scale.setScalar(opts.startScale ?? 1);
    this.scene.add(mesh);
    this.items.push({
      mesh, t: 0, dur: opts.duration ?? 0.5, startScale: opts.startScale ?? 1,
      endScale: opts.endScale ?? 4, opacity: material.opacity, rise: opts.rise ?? 0,
    });
    return mesh;
  }

  spawnSlash(position, facing, color = 0x9d7bff, opts = {}) {
    const group = new THREE.Group();
    group.position.copy(position);
    group.position.y = opts.y ?? 1.5;
    group.rotation.y = facing;
    const theta = opts.theta ?? 1.9;
    const geo = new THREE.RingGeometry(opts.inner ?? 0.6, opts.outer ?? 2.4, 36, 1, -theta / 2, theta);
    const material = new THREE.MeshBasicMaterial({
      color, transparent: true, opacity: 0.92, side: THREE.DoubleSide,
      blending: THREE.AdditiveBlending, depthWrite: false,
    });
    const mesh = new THREE.Mesh(geo, material);
    mesh.rotation.x = -Math.PI / 2;
    mesh.rotation.z = opts.spin ?? 0;
    group.add(mesh);
    const glowGeo = new THREE.RingGeometry((opts.inner ?? 0.6) * 0.7, (opts.outer ?? 2.4) * 1.04, 36, 1, -theta / 2, theta);
    const glowMat = new THREE.MeshBasicMaterial({
      color: 0xffffff, transparent: true, opacity: 0.2, side: THREE.DoubleSide,
      blending: THREE.AdditiveBlending, depthWrite: false,
    });
    const glow = new THREE.Mesh(glowGeo, glowMat);
    glow.rotation.x = -Math.PI / 2;
    group.add(glow);
    this.scene.add(group);
    this.items.push({
      mesh: group, t: 0, dur: opts.duration ?? 0.28, startScale: 0.72,
      endScale: opts.endScale ?? 1.35, opacity: 0.92, rise: 0, spin: opts.spinSpeed ?? 0,
    });
    return group;
  }

  flameSlash(position, facing, radius = 7) {
    for (let i = 0; i < 4; i++) {
      const angle = facing + (i - 1.5) * 0.22;
      const dist = 2.2 + i * 0.8;
      const p = position.clone().add(new THREE.Vector3(Math.sin(angle) * dist, 0.9 + Math.random() * 1.1, Math.cos(angle) * dist));
      this.particles.spawn(p, i % 2 ? 0xff8b3d : 0xff4a2e, 20, {
        speed: 3.2, size: 0.42, life: 0.7, gravity: -2, up: 0.4, spread: 1.5,
        direction: new THREE.Vector3(Math.sin(angle), 0.1, Math.cos(angle)),
      });
    }
    this.spawnSlash(position, facing, 0xff6a2f, { inner: 1, outer: radius, theta: 1.6, duration: 0.45, endScale: 1.5 });
    this.spawnSlash(position, facing, 0xffd08a, { inner: 0.4, outer: radius * 0.8, theta: 1.35, duration: 0.34, endScale: 1.7 });
  }

  shadowStep(from, to, color = 0x8d63ff) {
    const dir = to.clone().sub(from);
    const steps = 8;
    for (let i = 0; i < steps; i++) {
      const p = from.clone().addScaledVector(dir, i / steps);
      p.y = 0.2 + Math.random() * 1.8;
      this.particles.spawn(p, i % 3 ? color : 0x2b115e, 9, { speed: 2.4, size: 0.26, life: 0.55, gravity: -1, up: 0.8 });
    }
    this.spawnRing(from, color, { endScale: 3.2, duration: 0.4 });
    this.spawnRing(to, color, { endScale: 3.8, duration: 0.55 });
  }

  arise(position) {
    const p = position.clone();
    for (let i = 0; i < 5; i++) {
      const ring = this.spawnRing(p, i % 2 ? 0x8f5cff : 0x3b197f, {
        endScale: 2.2 + i * 0.8, duration: 0.7 + i * 0.15, y: 0.08 + i * 0.03, opacity: 0.55 - i * 0.06,
      });
      ring.position.x += (Math.random() - 0.5) * 1.2;
      ring.position.z += (Math.random() - 0.5) * 1.2;
    }
    this.particles.spawn(p.clone().setY(0.3), 0x7b4cff, 65, { speed: 2.2, size: 0.26, life: 1.5, gravity: -3.8, up: 1.2, spread: 1.4, drag: 0.94 });
    this.particles.spawn(p.clone().setY(0.2), 0x1b0b3c, 30, { speed: 3.5, size: 0.45, life: 1.1, gravity: -1, up: 0.6, spread: 1.7 });
  }

  domain(position) {
    const p = position.clone();
    for (let i = 0; i < 7; i++) {
      const ring = this.spawnRing(p, i % 2 ? 0xb28cff : 0x6d3bff, {
        endScale: 14 + i * 2.2, duration: 0.85 + i * 0.09, y: 0.06 + i * 0.03, opacity: 0.55 - i * 0.05,
      });
    }
    const pillarMat = new THREE.MeshBasicMaterial({
      color: 0x7d4cff, transparent: true, opacity: 0.14, side: THREE.DoubleSide,
      blending: THREE.AdditiveBlending, depthWrite: false,
    });
    const pillar = new THREE.Mesh(new THREE.CylinderGeometry(10.8, 10.8, 9, 64, 1, true), pillarMat);
    pillar.position.copy(p).setY(4.5);
    this.scene.add(pillar);
    this.items.push({ mesh: pillar, t: 0, dur: 1.4, startScale: 0.6, endScale: 1.05, opacity: 0.14, rise: 0 });
    this.particles.spawn(p.clone().setY(0.4), 0x8e5dff, 150, { speed: 5, size: 0.26, life: 1.6, gravity: -4.5, up: 1.4, spread: 1.5, drag: 0.94 });
    this.particles.spawn(p.clone().setY(0.5), 0xffffff, 30, { speed: 3, size: 0.18, life: 1.1, gravity: -2, up: 1.6, spread: 1 });
  }

  bossSlam(position) {
    this.spawnRing(position, 0xff2949, { endScale: 9, duration: 0.65, opacity: 0.65 });
    this.spawnRing(position, 0xff7a4a, { endScale: 5, duration: 0.4, opacity: 0.45 });
    this.particles.spawn(position.clone().setY(0.2), 0xff3d52, 70, { speed: 7, size: 0.28, life: 0.85, gravity: 13, up: 0.8 });
    this.particles.spawn(position.clone().setY(0.2), 0x3a1120, 25, { speed: 4, size: 0.5, life: 1, gravity: 3, up: 0.8 });
  }

  heal(position) {
    this.particles.spawn(position.clone().setY(1), 0x6dffc2, 25, { speed: 2, size: 0.16, life: 1.2, gravity: -4, up: 1.4, drag: 0.95 });
  }

  update(dt) {
    this.particles.update(dt);
    this.trail.update(dt);
    for (let i = this.items.length - 1; i >= 0; i--) {
      const item = this.items[i];
      item.t += dt;
      const p = item.t / item.dur;
      if (p >= 1) {
        this.scene.remove(item.mesh);
        item.mesh.traverse(o => {
          if (o.geometry) o.geometry.dispose();
          if (o.material) {
            if (Array.isArray(o.material)) o.material.forEach(m => m.dispose());
            else o.material.dispose();
          }
        });
        this.items.splice(i, 1);
        continue;
      }
      const ease = 1 - Math.pow(1 - p, 3);
      const scale = item.startScale + (item.endScale - item.startScale) * ease;
      item.mesh.scale.setScalar(scale);
      if (item.rise) item.mesh.position.y += item.rise * dt;
      if (item.spin) item.mesh.rotation.z += item.spin * dt;
      const fade = 1 - p;
      item.mesh.traverse(o => {
        if (o.material && o.material.transparent && o.material.opacity !== undefined) {
          if (!o.userData.__baseOpacity) o.userData.__baseOpacity = o.material.opacity;
          o.material.opacity = o.userData.__baseOpacity * fade;
        }
      });
    }
  }
}

import * as THREE from 'three';
import { mat, box } from './models.js';

const TAU = Math.PI * 2;

function seeded(seed = 1) {
  let s = seed;
  return () => {
    s = (s * 16807) % 2147483647;
    return (s - 1) / 2147483646;
  };
}

function makeStoneTexture(size = 1024) {
  const canvas = document.createElement('canvas');
  canvas.width = canvas.height = size;
  const ctx = canvas.getContext('2d');
  const rand = seeded(9231);
  ctx.fillStyle = '#20202c';
  ctx.fillRect(0, 0, size, size);
  // Large flagstones.
  const rows = 9;
  const rowH = size / rows;
  for (let row = 0; row < rows; row++) {
    let x = -rand() * 90;
    const y = row * rowH;
    while (x < size) {
      const w = 65 + rand() * 120;
      const shade = 24 + Math.floor(rand() * 17);
      ctx.fillStyle = `rgb(${shade},${shade + 2},${shade + 10})`;
      ctx.fillRect(x + 3, y + 3, w - 6, rowH - 6);
      ctx.strokeStyle = 'rgba(100,96,135,.09)';
      ctx.lineWidth = 1;
      ctx.strokeRect(x + 3, y + 3, w - 6, rowH - 6);
      // Cracks.
      if (rand() > 0.63) {
        ctx.strokeStyle = 'rgba(4,4,10,.45)';
        ctx.beginPath();
        let cx = x + w * 0.3;
        let cy = y + 10;
        ctx.moveTo(cx, cy);
        for (let k = 0; k < 4; k++) {
          cx += (rand() - 0.5) * 24;
          cy += rowH / 5;
          ctx.lineTo(cx, cy);
        }
        ctx.stroke();
      }
      // Violet mineral veins.
      if (rand() > 0.83) {
        ctx.strokeStyle = 'rgba(109,76,195,.2)';
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(x + 10, y + rowH * rand());
        ctx.lineTo(x + w - 10, y + rowH * rand());
        ctx.stroke();
      }
      x += w;
    }
  }
  // Grime and tiny stones.
  for (let i = 0; i < 1300; i++) {
    ctx.fillStyle = rand() > 0.5 ? 'rgba(0,0,0,.18)' : 'rgba(160,150,210,.07)';
    const r = rand() * 2.6 + 0.4;
    ctx.beginPath();
    ctx.arc(rand() * size, rand() * size, r, 0, TAU);
    ctx.fill();
  }
  const tex = new THREE.CanvasTexture(canvas);
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

function makeRuneTexture(size = 1024, seed = 3) {
  const canvas = document.createElement('canvas');
  canvas.width = canvas.height = size;
  const ctx = canvas.getContext('2d');
  const rand = seeded(seed);
  ctx.clearRect(0, 0, size, size);
  ctx.translate(size / 2, size / 2);
  const glow = ctx.createRadialGradient(0, 0, size * 0.15, 0, 0, size * 0.5);
  glow.addColorStop(0, 'rgba(95,55,220,0)');
  glow.addColorStop(0.55, 'rgba(105,63,230,.04)');
  glow.addColorStop(0.8, 'rgba(133,84,255,.12)');
  glow.addColorStop(1, 'rgba(80,38,180,0)');
  ctx.fillStyle = glow;
  ctx.fillRect(-size / 2, -size / 2, size, size);
  ctx.shadowColor = '#8a58ff';
  ctx.shadowBlur = 14;
  const drawCircle = (r, width, alpha = 1) => {
    ctx.strokeStyle = `rgba(154,116,255,${alpha})`;
    ctx.lineWidth = width;
    ctx.beginPath();
    ctx.arc(0, 0, r, 0, TAU);
    ctx.stroke();
  };
  drawCircle(size * 0.44, 2, 0.75);
  drawCircle(size * 0.43, 1, 0.4);
  drawCircle(size * 0.31, 1.4, 0.45);
  drawCircle(size * 0.19, 1, 0.3);
  // Radial ticks.
  for (let i = 0; i < 72; i++) {
    const a = (i / 72) * TAU;
    const len = i % 6 === 0 ? 28 : 10;
    ctx.strokeStyle = `rgba(180,148,255,${i % 6 === 0 ? 0.68 : 0.28})`;
    ctx.lineWidth = i % 6 === 0 ? 2 : 1;
    ctx.beginPath();
    ctx.moveTo(Math.cos(a) * size * 0.44, Math.sin(a) * size * 0.44);
    ctx.lineTo(Math.cos(a) * (size * 0.44 - len), Math.sin(a) * (size * 0.44 - len));
    ctx.stroke();
  }
  // Sigils between rings.
  ctx.shadowBlur = 8;
  for (let i = 0; i < 16; i++) {
    const a = (i / 16) * TAU;
    const r = size * 0.375;
    ctx.save();
    ctx.translate(Math.cos(a) * r, Math.sin(a) * r);
    ctx.rotate(a + Math.PI / 2);
    ctx.strokeStyle = 'rgba(194,164,255,.62)';
    ctx.lineWidth = 1.6;
    ctx.beginPath();
    const s = 9 + rand() * 8;
    for (let k = 0; k < 4; k++) {
      const aa = (k / 4) * TAU + (rand() > 0.5 ? 0.3 : 0);
      ctx.lineTo(Math.cos(aa) * s, Math.sin(aa) * s);
    }
    ctx.closePath();
    ctx.stroke();
    ctx.restore();
  }
  // Central seal.
  ctx.shadowBlur = 16;
  ctx.strokeStyle = 'rgba(172,138,255,.7)';
  ctx.lineWidth = 2;
  for (let k = 0; k < 2; k++) {
    ctx.save();
    ctx.rotate(k * Math.PI / 4);
    ctx.strokeRect(-size * 0.115, -size * 0.115, size * 0.23, size * 0.23);
    ctx.restore();
  }
  ctx.strokeStyle = 'rgba(116,231,255,.35)';
  ctx.lineWidth = 1;
  ctx.beginPath();
  for (let i = 0; i < 6; i++) {
    const a = (i / 6) * TAU;
    const x = Math.cos(a) * size * 0.13;
    const y = Math.sin(a) * size * 0.13;
    if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
  }
  ctx.closePath();
  ctx.stroke();
  const tex = new THREE.CanvasTexture(canvas);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

function makeGlowTexture() {
  const canvas = document.createElement('canvas');
  canvas.width = canvas.height = 256;
  const ctx = canvas.getContext('2d');
  const g = ctx.createRadialGradient(128, 128, 0, 128, 128, 128);
  g.addColorStop(0, 'rgba(255,255,255,1)');
  g.addColorStop(0.12, 'rgba(220,208,255,.9)');
  g.addColorStop(0.36, 'rgba(151,112,255,.32)');
  g.addColorStop(0.7, 'rgba(90,50,190,.08)');
  g.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, 256, 256);
  return new THREE.CanvasTexture(canvas);
}

function makePetalTexture() {
  const canvas = document.createElement('canvas');
  canvas.width = canvas.height = 64;
  const ctx = canvas.getContext('2d');
  const g = ctx.createRadialGradient(24, 22, 2, 32, 32, 30);
  g.addColorStop(0, 'rgba(255,230,246,1)');
  g.addColorStop(0.5, 'rgba(255,158,211,.92)');
  g.addColorStop(1, 'rgba(186,80,157,0)');
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.ellipse(32, 32, 15, 25, 0.5, 0, TAU);
  ctx.fill();
  return new THREE.CanvasTexture(canvas);
}

function makeMoonTexture() {
  const canvas = document.createElement('canvas');
  canvas.width = canvas.height = 512;
  const ctx = canvas.getContext('2d');
  const rand = seeded(777);
  const g = ctx.createRadialGradient(200, 190, 20, 256, 256, 250);
  g.addColorStop(0, '#f3f0ff');
  g.addColorStop(0.55, '#d8d2f4');
  g.addColorStop(0.86, '#aea6d4');
  g.addColorStop(1, 'rgba(150,140,200,0)');
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.arc(256, 256, 245, 0, TAU);
  ctx.fill();
  for (let i = 0; i < 48; i++) {
    const x = 90 + rand() * 330;
    const y = 80 + rand() * 350;
    const r = 4 + rand() * 22;
    ctx.fillStyle = `rgba(110,104,160,${0.04 + rand() * 0.09})`;
    ctx.beginPath();
    ctx.arc(x, y, r, 0, TAU);
    ctx.fill();
  }
  const tex = new THREE.CanvasTexture(canvas);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

function makeSky() {
  const uniforms = { uTime: { value: 0 } };
  const material = new THREE.ShaderMaterial({
    uniforms,
    side: THREE.BackSide,
    depthWrite: false,
    fog: false,
    vertexShader: /* glsl */`
      varying vec3 vWorld;
      void main() {
        vec4 wp = modelMatrix * vec4(position, 1.0);
        vWorld = wp.xyz;
        gl_Position = projectionMatrix * viewMatrix * wp;
      }
    `,
    fragmentShader: /* glsl */`
      varying vec3 vWorld;
      uniform float uTime;
      float hash(vec2 p) { return fract(sin(dot(p, vec2(127.1,311.7))) * 43758.5453123); }
      float noise(vec2 p) {
        vec2 i = floor(p); vec2 f = fract(p);
        f = f*f*(3.0-2.0*f);
        return mix(mix(hash(i),hash(i+vec2(1,0)),f.x),mix(hash(i+vec2(0,1)),hash(i+vec2(1,1)),f.x),f.y);
      }
      float fbm(vec2 p) {
        float v = 0.0; float a = 0.5;
        for (int i=0;i<5;i++){ v += a*noise(p); p*=2.03; a*=0.5; }
        return v;
      }
      void main() {
        vec3 d = normalize(vWorld);
        float y = clamp(d.y, -0.2, 1.0);
        vec3 zenith = vec3(0.012, 0.014, 0.045);
        vec3 mid = vec3(0.055, 0.035, 0.12);
        vec3 horizon = vec3(0.19, 0.075, 0.20);
        vec3 col = mix(horizon, mid, smoothstep(-0.02, 0.28, y));
        col = mix(col, zenith, smoothstep(0.2, 0.9, y));
        float neb = fbm(d.xz * 2.8 + d.y * 1.2);
        float neb2 = fbm(d.xz * 5.2 - d.y * 0.4);
        col += vec3(0.12, 0.035, 0.18) * smoothstep(0.38, 0.82, neb) * (1.0 - y * 0.5);
        col += vec3(0.02, 0.09, 0.14) * smoothstep(0.5, 0.9, neb2) * (1.0 - y);
        // Stars.
        vec2 sp = floor(d.xz / max(0.002, 0.0035 + abs(d.y) * 0.006));
        float star = step(0.993, hash(sp)) * smoothstep(0.02, 0.35, y);
        float tw = 0.55 + 0.45 * sin(uTime * 1.6 + hash(sp) * 40.0);
        col += vec3(0.72, 0.78, 1.0) * star * tw * 1.7;
        // Thin horizon haze.
        col += vec3(0.28, 0.13, 0.26) * exp(-abs(y) * 18.0) * 0.55;
        gl_FragColor = vec4(col, 1.0);
      }
    `,
  });
  const sky = new THREE.Mesh(new THREE.SphereGeometry(280, 48, 32), material);
  sky.frustumCulled = false;
  return { sky, uniforms };
}

function makeAurora(colorA, colorB, seed = 0) {
  const uniforms = { uTime: { value: 0 }, uColorA: { value: new THREE.Color(colorA) }, uColorB: { value: new THREE.Color(colorB) }, uSeed: { value: seed } };
  const material = new THREE.ShaderMaterial({
    uniforms, transparent: true, depthWrite: false, side: THREE.DoubleSide,
    blending: THREE.AdditiveBlending, fog: false,
    vertexShader: /* glsl */`
      varying vec2 vUv;
      void main(){ vUv=uv; gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.0); }
    `,
    fragmentShader: /* glsl */`
      varying vec2 vUv;
      uniform float uTime; uniform vec3 uColorA; uniform vec3 uColorB; uniform float uSeed;
      float hash(vec2 p){ return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453); }
      float noise(vec2 p){ vec2 i=floor(p); vec2 f=fract(p); f=f*f*(3.0-2.0*f);
        return mix(mix(hash(i),hash(i+vec2(1,0)),f.x),mix(hash(i+vec2(0,1)),hash(i+vec2(1,1)),f.x),f.y); }
      void main(){
        float wave = sin(vUv.x*7.0 + uTime*0.18 + uSeed)*0.5+0.5;
        float wave2 = sin(vUv.x*13.0 - uTime*0.11 + uSeed*2.0)*0.5+0.5;
        float curtain = smoothstep(0.05,0.55,vUv.y)*(1.0-smoothstep(0.68,1.0,vUv.y));
        float streak = smoothstep(0.35,0.95, noise(vec2(vUv.x*9.0+uTime*0.04, vUv.y*2.5+uSeed)));
        float a = curtain * (0.18 + wave*0.25 + wave2*0.12) * (0.35 + streak*0.85);
        vec3 col = mix(uColorA, uColorB, vUv.y*0.8 + wave*0.15);
        gl_FragColor = vec4(col, a*0.65);
      }
    `,
  });
  const mesh = new THREE.Mesh(new THREE.PlaneGeometry(170, 42, 32, 8), material);
  return { mesh, uniforms };
}

