  }));
  moonRing.position.copy(moon.position);
  moonRing.lookAt(0, 5, 0);
  scene.add(moonRing);

  // Lighting.
  const hemi = new THREE.HemisphereLight(0x7e75e8, 0x180c18, 1.25);
  scene.add(hemi);
  const moonLight = new THREE.DirectionalLight(0xb9c2ff, 2.5);
  moonLight.position.set(-24, 38, 20);
  moonLight.castShadow = true;
  moonLight.shadow.mapSize.set(1536, 1536);
  moonLight.shadow.camera.left = -34;
  moonLight.shadow.camera.right = 34;
  moonLight.shadow.camera.top = 34;
  moonLight.shadow.camera.bottom = -34;
  moonLight.shadow.camera.near = 1;
  moonLight.shadow.camera.far = 100;
  moonLight.shadow.bias = -0.0008;
  moonLight.shadow.normalBias = 0.03;
  scene.add(moonLight);
  const rim = new THREE.DirectionalLight(0x6f3fff, 1.1);
  rim.position.set(25, 14, -30);
  scene.add(rim);
  const fill = new THREE.DirectionalLight(0xff7a4a, 0.45);
  fill.position.set(10, 8, 30);
  scene.add(fill);

  // Arena base.
  const stoneTex = makeStoneTexture();
  stoneTex.anisotropy = Math.min(8, renderer.capabilities.getMaxAnisotropy());
  const arenaSideMat = mat(0x171621, { roughness: 0.96 });
  const base = new THREE.Mesh(new THREE.CylinderGeometry(29, 30.5, 2.4, 16), arenaSideMat);
  base.position.y = -1.2;
  base.receiveShadow = true;
  base.castShadow = true;
  scene.add(base);
  const lower = new THREE.Mesh(new THREE.CylinderGeometry(28.5, 19, 8, 16), mat(0x0f0d18, { roughness: 1 }));
  lower.position.y = -6.2;
  scene.add(lower);
  const step = new THREE.Mesh(new THREE.CylinderGeometry(31, 31.4, 0.45, 16), mat(0x1f1c2c, { roughness: 0.95 }));
  step.position.y = -0.2;
  step.receiveShadow = true;
  scene.add(step);
  const groundMat = new THREE.MeshStandardMaterial({
    map: stoneTex, roughness: 0.9, metalness: 0.06, color: 0x8e8ba8,
  });
  const ground = new THREE.Mesh(new THREE.CircleGeometry(28.6, 72), groundMat);
  ground.rotation.x = -Math.PI / 2;
  ground.position.y = 0.02;
  ground.receiveShadow = true;
  scene.add(ground);
  // Dark edge ring.
  const edgeRing = new THREE.Mesh(new THREE.RingGeometry(27.6, 28.65, 80), new THREE.MeshStandardMaterial({
    color: 0x1d1929, roughness: 0.75, metalness: 0.3, emissive: 0x1d0c37, emissiveIntensity: 0.4,
  }));
  edgeRing.rotation.x = -Math.PI / 2;
  edgeRing.position.y = 0.035;
  scene.add(edgeRing);

  // Central rune seal.
  const runeTex = makeRuneTexture();
  const runeMat = new THREE.MeshBasicMaterial({
    map: runeTex, transparent: true, opacity: 0.58, blending: THREE.AdditiveBlending,
    depthWrite: false, side: THREE.DoubleSide,
  });
  const rune = new THREE.Mesh(new THREE.CircleGeometry(13, 64), runeMat);
  rune.rotation.x = -Math.PI / 2;
  rune.position.y = 0.045;
  scene.add(rune);
  const rune2 = new THREE.Mesh(new THREE.CircleGeometry(9.4, 64), new THREE.MeshBasicMaterial({
    map: makeRuneTexture(1024, 17), transparent: true, opacity: 0.32, blending: THREE.AdditiveBlending,
    depthWrite: false, side: THREE.DoubleSide,
  }));
  rune2.rotation.x = -Math.PI / 2;
  rune2.position.y = 0.05;
  scene.add(rune2);
  const runeLight = new THREE.PointLight(0x7548ff, 38, 34, 2);
  runeLight.position.set(0, 2.2, 0);
  scene.add(runeLight);

  const barrierUniforms = { uTime: { value: 0 }, uOpacity: { value: 0.1 } };
  const barrierMat = new THREE.ShaderMaterial({
    uniforms: barrierUniforms,
    transparent: true, depthWrite: false, side: THREE.DoubleSide,
    blending: THREE.AdditiveBlending,
    vertexShader: /* glsl */`
      varying vec2 vUv; varying vec3 vPos;
      void main(){ vUv=uv; vPos=position; gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.0); }
    `,
    fragmentShader: /* glsl */`
      varying vec2 vUv; varying vec3 vPos;
      uniform float uTime; uniform float uOpacity;
      float hash(vec2 p){ return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453); }
      void main(){
        float fade = smoothstep(0.0,0.12,vUv.y) * (1.0-smoothstep(0.55,1.0,vUv.y));
        float scan = smoothstep(0.84,1.0,sin(vUv.y*190.0 - uTime*2.5)*0.5+0.5);
        float grid = step(0.97, max(sin(vUv.x*140.0)*0.5+0.5, sin(vUv.y*80.0)*0.5+0.5));
        float n = hash(vec2(floor(vUv.x*80.0), floor(vUv.y*16.0)+floor(uTime*3.0)));
        vec3 col = mix(vec3(0.32,0.15,0.75), vec3(0.4,0.86,1.0), vUv.y);
        float a = (fade*0.18 + scan*0.35 + grid*0.07 + step(0.992,n)*0.4) * uOpacity;
        gl_FragColor = vec4(col, a);
      }
    `,
  });
  const barrier = new THREE.Mesh(new THREE.CylinderGeometry(28.8, 28.8, 13, 80, 1, true), barrierMat);
  barrier.position.y = 6.5;
  scene.add(barrier);

  const flameTexture = makeGlowTexture();
  const torii = makeTorii(scene, flameTexture);

  // Pillars.
  const pillars = [];
  for (let i = 0; i < 8; i++) {
    const a = (i / 8) * TAU + 0.2;
    const p = makePillar(scene, Math.cos(a) * 24.8, Math.sin(a) * 24.8, -a, flameTexture);
    pillars.push(p);
  }
  // Torii gets two extra flames.
  const toriiFlames = [];

  const swordMonument = makeSwordMonument(scene);
  const rand = seeded(4421);
  const trees = [];
  const treePositions = [
    [-20.4, 9.2, 0.95], [21.2, 5.8, 0.85], [-13.5, 19.5, 1.05],
    [12.5, 20.5, 0.78], [-22.5, -7.5, 0.9], [23.2, -5.2, 0.82],
  ];
  for (const [x, z, s] of treePositions) trees.push(makeTree(scene, x, z, s, rand));

  // Crystals.
  const crystalMat = new THREE.MeshStandardMaterial({
    color: 0x5d3ac9, emissive: 0x6c3dff, emissiveIntensity: 1.1, roughness: 0.28,
    metalness: 0.35, transparent: true, opacity: 0.88, flatShading: true,
  });
  const crystals = [];
  for (let i = 0; i < 11; i++) {
    const a = rand() * TAU;
    const r = 11 + rand() * 15;
    const g = new THREE.Group();
    g.position.set(Math.cos(a) * r, 0, Math.sin(a) * r);
    const count = 2 + Math.floor(rand() * 3);
    for (let k = 0; k < count; k++) {
      const c = new THREE.Mesh(new THREE.OctahedronGeometry(0.25 + rand() * 0.45, 0), crystalMat);
      c.scale.y = 2.5 + rand() * 2.5;
      c.position.set((rand() - 0.5) * 0.9, 0.3 + c.scale.y * 0.18, (rand() - 0.5) * 0.9);
      c.rotation.z = (rand() - 0.5) * 0.4;
      c.castShadow = true;
      g.add(c);
    }
    const light = new THREE.PointLight(0x7d4dff, 4, 6, 2);
    light.position.y = 0.7;
    g.add(light);
    scene.add(g);
    crystals.push(g);
  }

  const pagoda = makePagoda(scene);
  const floatingRocks = [];
  const rockData = [
    [-70, 34, -88, 5], [56, 27, -82, 4], [78, 44, -130, 6], [-35, 25, -58, 3.2],
    [38, 18, -48, 2.4], [-92, 20, -40, 4.5], [8, 40, -110, 3.5], [96, 33, -70, 5],
  ];
  for (const [x, y, z, s] of rockData) floatingRocks.push(makeFloatingRock(scene, x, y, z, s, rand));

  // Distant mountain silhouettes.
  const mountainMat = new THREE.MeshBasicMaterial({ color: 0x100d1c, fog: true });
  for (let i = 0; i < 11; i++) {
    const a = -0.9 + i * 0.18;
    const r = 150 + rand() * 35;
    const h = 25 + rand() * 30;
    const m = new THREE.Mesh(new THREE.ConeGeometry(18 + rand() * 22, h, 4), mountainMat);
    m.position.set(Math.cos(a) * r, h * 0.5 - 8, Math.sin(a) * r);
    m.rotation.y = rand() * TAU;
    scene.add(m);
  }

  // Ground mist sprites.
  const mistTex = (() => {
    const c = document.createElement('canvas'); c.width = c.height = 256;
    const x = c.getContext('2d');
    const g = x.createRadialGradient(128, 128, 10, 128, 128, 128);
    g.addColorStop(0, 'rgba(118,92,190,.16)');
    g.addColorStop(0.5, 'rgba(80,60,140,.06)');
    g.addColorStop(1, 'rgba(0,0,0,0)');
    x.fillStyle = g; x.fillRect(0, 0, 256, 256);
    return new THREE.CanvasTexture(c);
  })();
  const mists = [];
  for (let i = 0; i < 9; i++) {
    const s = new THREE.Sprite(new THREE.SpriteMaterial({
      map: mistTex, transparent: true, opacity: 0.38, depthWrite: false, blending: THREE.AdditiveBlending,
    }));
    const a = rand() * TAU;
    const r = 7 + rand() * 19;
    s.position.set(Math.cos(a) * r, 0.35 + rand() * 0.5, Math.sin(a) * r);
    s.scale.set(12 + rand() * 12, 3 + rand() * 2, 1);
    scene.add(s);
    mists.push({ sprite: s, a, r, speed: 0.02 + rand() * 0.03 });
  }

  // Falling petals.
  const petalTex = makePetalTexture();
  const petalCount = 320;
  const petalGeo = new THREE.BufferGeometry();
  const petalPos = new Float32Array(petalCount * 3);
  const petalData = [];
  for (let i = 0; i < petalCount; i++) {
    const a = rand() * TAU;
    const r = rand() * 34;
    petalPos[i * 3] = Math.cos(a) * r;
    petalPos[i * 3 + 1] = rand() * 18 + 1;
    petalPos[i * 3 + 2] = Math.sin(a) * r;
    petalData.push({ speed: 0.25 + rand() * 0.55, sway: rand() * TAU, swaySpeed: 0.5 + rand() * 1.2, drift: 0.2 + rand() * 0.5 });
  }
  petalGeo.setAttribute('position', new THREE.BufferAttribute(petalPos, 3));
  const petalMat = new THREE.PointsMaterial({
    map: petalTex, color: 0xffb5da, size: 0.34, transparent: true, opacity: 0.85,
    depthWrite: false, alphaTest: 0.05, sizeAttenuation: true,
  });
  const petals = new THREE.Points(petalGeo, petalMat);
  petals.frustumCulled = false;
  scene.add(petals);

  // Embers around arena.
  const emberCount = 160;
  const emberGeo = new THREE.BufferGeometry();
  const emberPos = new Float32Array(emberCount * 3);
  const emberData = [];
  for (let i = 0; i < emberCount; i++) {
    const a = rand() * TAU;
    const r = 14 + rand() * 14;
    emberPos[i * 3] = Math.cos(a) * r;
    emberPos[i * 3 + 1] = rand() * 7;
    emberPos[i * 3 + 2] = Math.sin(a) * r;
    emberData.push({ speed: 0.25 + rand() * 0.6, phase: rand() * TAU, baseX: emberPos[i * 3], baseZ: emberPos[i * 3 + 2] });
  }
  emberGeo.setAttribute('position', new THREE.BufferAttribute(emberPos, 3));
  const emberMat = new THREE.PointsMaterial({
    map: flameTexture, color: 0xff7c46, size: 0.2, transparent: true, opacity: 0.85,
    blending: THREE.AdditiveBlending, depthWrite: false, sizeAttenuation: true,
  });
  const embers = new THREE.Points(emberGeo, emberMat);
  embers.frustumCulled = false;
  scene.add(embers);

  // Dust motes.
  const dustCount = 220;
  const dustGeo = new THREE.BufferGeometry();
  const dustPos = new Float32Array(dustCount * 3);
  const dustData = [];
  for (let i = 0; i < dustCount; i++) {
    dustPos[i * 3] = (rand() - 0.5) * 56;
    dustPos[i * 3 + 1] = rand() * 9 + 0.4;
    dustPos[i * 3 + 2] = (rand() - 0.5) * 56;
    dustData.push({ phase: rand() * TAU, speed: 0.05 + rand() * 0.15, y: dustPos[i * 3 + 1] });
  }
  dustGeo.setAttribute('position', new THREE.BufferAttribute(dustPos, 3));
  const dust = new THREE.Points(dustGeo, new THREE.PointsMaterial({
    map: flameTexture, color: 0xb7a8ff, size: 0.07, transparent: true, opacity: 0.45,
    blending: THREE.AdditiveBlending, depthWrite: false, sizeAttenuation: true,
  }));
  dust.frustumCulled = false;
  scene.add(dust);

  const bossMood = { active: false, amount: 0 };
  const baseFog = new THREE.Color(0x0b0718);
  const bossFog = new THREE.Color(0x1b0512);

  let time = 0;
  const update = (dt, playerPos, boundaryDanger = 0) => {
    time += dt;
    skyUniforms.uTime.value = time;
    aurora1.uniforms.uTime.value = time;
    aurora2.uniforms.uTime.value = time;
    rune.rotation.z += dt * 0.035;
    rune2.rotation.z -= dt * 0.055;
    runeMat.opacity = 0.5 + Math.sin(time * 1.4) * 0.1;
    runeLight.intensity = 32 + Math.sin(time * 2.1) * 8;
    barrierUniforms.uTime.value = time;
    barrierUniforms.uOpacity.value += (0.08 + boundaryDanger * 0.9 - barrierUniforms.uOpacity.value) * Math.min(1, dt * 4);
    // Torii lantern flicker.
    torii.children.forEach(c => {
      if (c.isSprite) c.material.opacity = 0.38 + Math.sin(time * 7 + c.position.x) * 0.08;
    });
    pillars.forEach((p, i) => {
      p.flame.scale.y = 2.1 + Math.sin(time * 8 + i * 2.1) * 0.25;
      p.light.intensity = 5.5 + Math.sin(time * 9 + i) * 1.4;
    });
    // Crystals pulse.
    crystals.forEach((g, i) => {
      g.rotation.y += dt * (0.05 + i * 0.004);
      g.children.forEach(c => { if (c.isPointLight) c.intensity = 3 + Math.sin(time * 2 + i) * 1.2; });
    });
    floatingRocks.forEach((g, i) => {
      g.position.y += Math.sin(time * 0.35 + i * 1.7) * dt * 0.16;
      g.rotation.y += dt * 0.006 * (i % 2 ? 1 : -1);
    });
    pagoda.position.y = 15 + Math.sin(time * 0.28) * 0.4;
    // Petals.
    const pp = petalGeo.attributes.position.array;
    for (let i = 0; i < petalCount; i++) {
      const d = petalData[i];
      pp[i * 3 + 1] -= d.speed * dt;
      pp[i * 3] += Math.sin(time * d.swaySpeed + d.sway) * d.drift * dt;
      pp[i * 3 + 2] += Math.cos(time * d.swaySpeed * 0.7 + d.sway) * d.drift * dt * 0.6;
      if (pp[i * 3 + 1] < 0.15) {
        pp[i * 3 + 1] = 15 + Math.random() * 4;
        const a = Math.random() * TAU;
        const r = 3 + Math.random() * 28;
        pp[i * 3] = Math.cos(a) * r;
        pp[i * 3 + 2] = Math.sin(a) * r;
      }
    }
    petalGeo.attributes.position.needsUpdate = true;
    // Embers.
    const ep = emberGeo.attributes.position.array;
    for (let i = 0; i < emberCount; i++) {
      const d = emberData[i];
      ep[i * 3 + 1] += d.speed * dt;
      ep[i * 3] += Math.sin(time * 0.7 + d.phase) * 0.12 * dt;
      if (ep[i * 3 + 1] > 8) {
        ep[i * 3 + 1] = 0.1;
        const a = Math.random() * TAU;
        const r = 12 + Math.random() * 16;
        ep[i * 3] = Math.cos(a) * r;
        ep[i * 3 + 2] = Math.sin(a) * r;
      }
    }
    emberGeo.attributes.position.needsUpdate = true;
    // Dust.
    const dp = dustGeo.attributes.position.array;
    for (let i = 0; i < dustCount; i++) {
      const d = dustData[i];
      dp[i * 3 + 1] = d.y + Math.sin(time * d.speed * 3 + d.phase) * 0.5;
      dp[i * 3] += Math.sin(time * 0.13 + d.phase) * 0.02 * dt;
    }
    dustGeo.attributes.position.needsUpdate = true;
    // Mist drift.
    mists.forEach((m, i) => {
      m.a += dt * m.speed;
      m.sprite.position.x = Math.cos(m.a) * m.r;
      m.sprite.position.z = Math.sin(m.a) * m.r;
      m.sprite.material.opacity = 0.22 + Math.sin(time * 0.5 + i) * 0.08;
    });
    // Boss mood.
    bossMood.amount += ((bossMood.active ? 1 : 0) - bossMood.amount) * Math.min(1, dt * 1.8);
    scene.fog.color.copy(baseFog).lerp(bossFog, bossMood.amount);
    hemi.color.setHex(0x7e75e8).lerp(new THREE.Color(0xc03b5c), bossMood.amount * 0.55);
    rim.color.setHex(0x6f3fff).lerp(new THREE.Color(0xff2747), bossMood.amount);
    rim.intensity = 1.1 + bossMood.amount * 0.9;
    runeLight.color.setHex(0x7548ff).lerp(new THREE.Color(0xff2957), bossMood.amount);
    if (playerPos) {
      // Keep the moon-facing atmosphere anchored; nothing needed yet.
    }
  };

  const setBossMood = (active) => { bossMood.active = active; };

  return {
    update, setBossMood, torii, pillars, rune, rune2, moon, moonGlow,
    get time() { return time; },
  };
}

import * as THREE from 'three';

const $ = (id) => document.getElementById(id);

const WAVE_NAMES = [
  '첫 번째 균열 · 그림자 임프 소탕',
  '붉은 달 · 심연의 사냥개',
  '검의 무덤 · 저주받은 검객',
  '균열 심부 · 정예 그림자',
  '왕좌 · 혈귀 장군',
];

const WAVE_SUBS = [
  '그림자 임프가 깨어났다',
  '사냥개가 피 냄새를 맡았다',
  '검객들이 그림자 속에서 일어선다',
  '정예 그림자가 균열을 지킨다',
  '혈귀 장군이 왕좌에서 내려온다',
];

export class UI {
  constructor() {
    this.cache = {};
    this.enemyLayer = document.createElement('div');
    this.enemyLayer.className = 'enemy-layer';
    $('hud').appendChild(this.enemyLayer);
    this.damageLayer = $('damage-layer');
    this.bars = new Map();
    this.lastCooldowns = {};
    this.lastCombo = 0;
    this.comboTimer = 0;
    this.toastTimer = null;
    this.bannerTimer = null;
    this.flashEl = document.createElement('div');
    this.flashEl.className = 'damage-flash';
    document.getElementById('app').appendChild(this.flashEl);
    this.projected = new THREE.Vector3();
  }

  el(id) {
    if (!this.cache[id]) this.cache[id] = $(id);
    return this.cache[id];
  }

  setLoading(p, copy) {
    const fill = this.el('load-fill');
    if (fill) fill.style.width = `${Math.round(p * 100)}%`;
    if (copy) this.el('load-copy').textContent = copy;
  }

  finishLoading() {
    this.el('loading').classList.add('out');
    setTimeout(() => this.el('loading').classList.add('hidden'), 800);
    this.el('start-screen').classList.remove('hidden');
  }

  showStart() {
    this.el('start-screen').classList.remove('hidden');
    this.el('hud').classList.add('hidden');
  }

  enterGame() {
    this.el('start-screen').classList.add('hidden');
    this.el('hud').classList.remove('hidden');
    document.body.classList.add('cinematic');
    setTimeout(() => document.body.classList.remove('cinematic'), 2200);
  }

  updateStats(p) {
    this.el('level-num').textContent = String(p.level).padStart(2, '0');
    this.el('hp-fill').style.width = `${Math.max(0, p.hp / p.maxHp) * 100}%`;
    this.el('hp-text').textContent = `${Math.ceil(p.hp)} / ${p.maxHp}`;
    this.el('mp-fill').style.width = `${Math.max(0, p.mp / p.maxMp) * 100}%`;
    this.el('mp-text').textContent = `${Math.floor(p.mp)} / ${p.maxMp}`;
    this.el('xp-fill').style.width = `${Math.min(100, p.xp / p.xpNext * 100)}%`;
    this.el('xp-text').textContent = `${Math.floor(p.xp)} / ${p.xpNext}`;
    this.el('rank-label').textContent = p.rank;
    this.el('soul-count').textContent = p.souls;
    this.el('flame-cost').textContent = p.flameUnlocked ? '20 MP' : 'LV.2 해금';
    this.el('dash-cost').textContent = '15 MP';
    this.el('arise-cost').textContent = p.ariseUnlocked ? `${p.ariseCost} MP` : 'LV.3 해금';
    this.el('domain-cost').textContent = p.level >= 4 ? `${p.domainCost} MP` : 'LV.4 해금';
  }

  setWave(wave, remaining, total) {
    this.el('wave-label').textContent = `WAVE ${String(wave).padStart(2, '0')}`;
    this.el('quest-name').textContent = WAVE_NAMES[Math.min(wave - 1, WAVE_NAMES.length - 1)] || `무한 균열 · WAVE ${wave}`;
    this.el('enemy-count').textContent = remaining;
    this.el('wave-progress').style.width = `${Math.min(100, (wave - 1) / 5 * 100)}%`;
    this.el('quest-sub').innerHTML = `<span>남은 적</span><b id="enemy-count">${remaining}</b><span>목표</span><b>${wave >= 5 ? '무한 균열' : '5 웨이브'}</b>`;
  }

  showBanner(kicker, title, sub, duration = 2100) {
    this.el('banner-kicker').textContent = kicker;
    this.el('banner-title').textContent = title;
    this.el('banner-sub').textContent = sub;
    const b = this.el('wave-banner');
    b.classList.remove('show');
    void b.offsetWidth;
    b.classList.add('show');
    clearTimeout(this.bannerTimer);
    this.bannerTimer = setTimeout(() => b.classList.remove('show'), duration);
  }

  hideBanner() {
    this.el('wave-banner').classList.remove('show');
  }

  showBoss(name, hp, max) {
    this.el('boss-wrap').classList.remove('hidden');
    this.el('boss-name').textContent = name;
    this.el('boss-fill').style.width = `${hp / max * 100}%`;
    this.el('boss-phase').textContent = 'PHASE I';
  }

  updateBoss(hp, max) {
    this.el('boss-fill').style.width = `${Math.max(0, hp / max) * 100}%`;
    this.el('boss-phase').textContent = hp / max < 0.45 ? 'PHASE II' : 'PHASE I';
  }

  hideBoss() {
    this.el('boss-wrap').classList.add('hidden');
  }

  setCombo(n, timer = 0) {
    this.comboTimer = timer;
    if (n > 0) {
      this.el('combo-wrap').classList.add('show');
      this.el('combo-num').textContent = n;
      const grade = n >= 30 ? 'MONARCH' : n >= 20 ? 'SOVEREIGN' : n >= 12 ? 'SLAYER' : n >= 6 ? 'HUNTER' : '';
      this.el('combo-grade').textContent = grade;
      if (n > this.lastCombo) {
        this.el('combo-num').animate(
          [{ transform: 'scale(1.25)' }, { transform: 'scale(1)' }],
          { duration: 130, easing: 'ease-out' }
        );
      }
    } else {
      this.el('combo-wrap').classList.remove('show');
    }
    this.lastCombo = n;
  }

  toast(text, type = '') {
    const t = this.el('toast');
    t.textContent = text;
    t.className = `toast show ${type}`;
    clearTimeout(this.toastTimer);
    this.toastTimer = setTimeout(() => t.classList.remove('show'), 2200);
  }

  damage(worldPos, amount, type = '') {
    if (!worldPos) return;
    const v = worldPos.clone();
    v.y += 0.6;
    v.project(this.camera);
    if (v.z > 1) return;
    const x = (v.x * 0.5 + 0.5) * window.innerWidth + (Math.random() - 0.5) * 24;
    const y = (-v.y * 0.5 + 0.5) * window.innerHeight + (Math.random() - 0.5) * 12;
    const d = document.createElement('div');
    d.className = `dmg ${type}`;
    d.textContent = type === 'heal' ? `+${amount}` : amount;
    d.style.left = `${x}px`;
    d.style.top = `${y}px`;
    this.damageLayer.appendChild(d);
    setTimeout(() => d.remove(), 780);
  }

  flash(color = 'red') {
    this.flashEl.className = `damage-flash ${color} on`;
    clearTimeout(this.flashTimer);
    this.flashTimer = setTimeout(() => this.flashEl.classList.remove('on'), 130);
  }

  setAbilityState(states) {
    for (const [name, s] of Object.entries(states)) {
      const cd = this.el(`cd-${name}`);
      if (!cd) continue;
      const prev = this.lastCooldowns[name] || 0;
      if (s.remaining > 0.02) {
        cd.classList.add('on');
        cd.style.setProperty('--cd', `${(1 - s.remaining / s.total) * 100}%`);
        cd.dataset.left = s.remaining >= 1 ? Math.ceil(s.remaining) : s.remaining.toFixed(1);
      } else {
        cd.classList.remove('on');
        if (prev > 0.02) {
          const btn = cd.parentElement;
          btn.classList.remove('ready-flash');
          void btn.offsetWidth;
          btn.classList.add('ready-flash');
        }
      }
      if (s.locked !== undefined) {
        cd.parentElement.classList.toggle('locked', s.locked);
        const tag = cd.parentElement.querySelector('.lock-tag');
        if (tag) tag.style.display = s.locked ? 'block' : 'none';
      }
      this.lastCooldowns[name] = s.remaining;
    }
  }

  deny(name) {
    const btn = document.querySelector(`.ability[data-action="${name}"]`);
    if (!btn) return;
    btn.classList.remove('denied');
    void btn.offsetWidth;
    btn.classList.add('denied');
  }

  setBoundary(danger) {
    const el = this.el('objective-text');
    if (danger > 0.1) el.textContent = '균열 경계가 무너지고 있다 — 안쪽으로 이동';
    else el.textContent = '균열의 제단을 지켜라';
  }

  updateEnemyBars(enemies, camera) {
    this.camera = camera;
    const alive = new Set();
    for (const e of enemies) {
      if (!e.alive) continue;
      alive.add(e.id);
      let bar = this.bars.get(e.id);
      if (!bar) {
        bar = document.createElement('div');
        bar.className = 'enemy-bar';
        bar.innerHTML = `<div class="enemy-name">${e.name}</div><div class="enemy-track"><i></i></div><div class="enemy-tier"></div>`;
        this.enemyLayer.appendChild(bar);
        this.bars.set(e.id, bar);
      }
      const v = e.group.position.clone();
      v.y += e.barHeight || 3.2;
      v.project(camera);
      if (v.z > 1 || v.z < -1) {
        bar.style.display = 'none';
        continue;
      }
      const x = (v.x * 0.5 + 0.5) * window.innerWidth;
      const y = (-v.y * 0.5 + 0.5) * window.innerHeight;
      if (x < -100 || x > window.innerWidth + 100 || y < -100 || y > window.innerHeight + 100) {
        bar.style.display = 'none';
        continue;
      }
      bar.style.display = '';
      bar.style.left = `${x}px`;
      bar.style.top = `${y}px`;
      bar.querySelector('i').style.width = `${Math.max(0, e.hp / e.maxHp) * 100}%`;
      bar.classList.toggle('elite', !!e.elite);
      bar.classList.toggle('boss', e.type === 'boss');
      bar.querySelector('.enemy-tier').textContent = e.elite ? 'ELITE' : '';
    }
    for (const [id, bar] of this.bars) {
      if (!alive.has(id)) {
        bar.remove();
        this.bars.delete(id);
      }
    }
  }

  drawRadar(player, enemies, shadows, yaw) {
    const canvas = this.el('radar');
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    const w = canvas.width;
    const h = canvas.height;
    const cx = w / 2;
    const cy = h / 2;
    ctx.clearRect(0, 0, w, h);
    ctx.save();
    ctx.translate(cx, cy);
    // Grid.
    ctx.strokeStyle = 'rgba(116,231,255,.1)';
    ctx.lineWidth = 1;
    for (let r = 28; r <= 92; r += 32) {
      ctx.beginPath();
      ctx.arc(0, 0, r, 0, Math.PI * 2);
      ctx.stroke();
    }
    ctx.beginPath();
    ctx.moveTo(-96, 0); ctx.lineTo(96, 0);
    ctx.moveTo(0, -96); ctx.lineTo(0, 96);
    ctx.strokeStyle = 'rgba(116,231,255,.06)';
    ctx.stroke();
    const scale = 92 / 32;
    const sin = Math.sin(yaw);
    const cos = Math.cos(yaw);
    const drawDot = (wx, wz, color, size, ring = false) => {
      const dx = wx - player.x;
      const dz = wz - player.z;
      const right = cos * dx - sin * dz;
      const forward = -sin * dx - cos * dz;
      const px = right * scale;
      const py = -forward * scale;
      if (Math.hypot(px, py) > 96) return;
      ctx.fillStyle = color;
      ctx.shadowColor = color;
      ctx.shadowBlur = 8;
      ctx.beginPath();
      ctx.arc(px, py, size, 0, Math.PI * 2);
      ctx.fill();
      ctx.shadowBlur = 0;
      if (ring) {
        ctx.strokeStyle = color;
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.arc(px, py, size + 3, 0, Math.PI * 2);
        ctx.stroke();
      }
    };
    for (const s of shadows) if (s.alive) drawDot(s.position.x, s.position.z, 'rgba(180,145,255,.75)', 2.2);
    for (const e of enemies) {
      if (!e.alive) continue;
      if (e.type === 'boss') drawDot(e.group.position.x, e.group.position.z, '#ff3f63', 5.5, true);
      else drawDot(e.group.position.x, e.group.position.z, e.elite ? '#ff9a5c' : '#ff627d', e.elite ? 3.5 : 2.4);
    }
    // Player.
    ctx.fillStyle = '#fff';
    ctx.shadowColor = '#74e7ff';
    ctx.shadowBlur = 12;
    ctx.beginPath();
    ctx.moveTo(0, -6);
    ctx.lineTo(4.5, 5);
    ctx.lineTo(0, 2.5);
    ctx.lineTo(-4.5, 5);
    ctx.closePath();
    ctx.fill();
    ctx.restore();
    const nearest = enemies.filter(e => e.alive).reduce((m, e) => {
      const d = Math.hypot(e.group.position.x - player.x, e.group.position.z - player.z);
      return Math.min(m, d);
    }, 999);
    this.el('radar-dist').textContent = nearest < 999 ? `${nearest.toFixed(0)}m` : 'CLEAR';
  }

  showLevelUp(level, cards, cb) {
    this.el('levelup').classList.remove('hidden');
    this.el('new-level').textContent = String(level).padStart(2, '0');
    const row = this.el('card-row');
    row.innerHTML = '';
    cards.forEach((card, i) => {
      const b = document.createElement('button');
      b.className = 'awaken-card';
      b.innerHTML = `
        <span class="card-index">0${i + 1}</span>
        <div class="card-glyph">${card.icon}</div>
        <h3>${card.name}</h3>
        <span class="card-type">${card.type}</span>
        <p>${card.desc}</p>
        <div class="card-stat">${card.stat}</div>`;
      b.addEventListener('click', () => cb(i));
      row.appendChild(b);
    });
    this.el('sp-left').textContent = '1 POINT';
  }

  hideLevelUp() {
    this.el('levelup').classList.add('hidden');
  }

  showPause() { this.el('pause').classList.remove('hidden'); }
  hidePause() { this.el('pause').classList.add('hidden'); }
  showHowto() { this.el('howto').classList.remove('hidden'); }
  hideHowto() { this.el('howto').classList.add('hidden'); }

  showResult({ victory, level, kills, combo, souls }) {
    this.el('result').classList.remove('hidden');
    this.el('result-kicker').textContent = victory ? 'RIFT CLEARED' : 'HUNTER DOWN';
    this.el('result-title').textContent = victory ? '균열을 닫았다' : '그림자가 삼켜졌다';
    this.el('result-desc').textContent = victory
      ? '그림자 군주가 세상에 그 이름을 새겼다. 무한 균열이 열려 있다.'
      : '하지만 그림자는 죽지 않는다. 다시 일어나 균열에 도전하라.';
    this.el('res-level').textContent = level;
    this.el('res-kills').textContent = kills;
    this.el('res-combo').textContent = combo;
    this.el('res-souls').textContent = souls;
    this.el('continue-btn').querySelector('span').textContent = victory ? '무한 균열 계속' : '다시 도전';
  }

  hideResult() { this.el('result').classList.add('hidden'); }

  setZone(text) { this.el('zone-label').textContent = text; }

  showMobile() {
    document.body.classList.add('is-mobile');
    this.el('mobile-controls').classList.remove('hidden');
  }

  hideMobile() {
    document.body.classList.remove('is-mobile');
    this.el('mobile-controls').classList.add('hidden');
  }

  reset() {
    this.bars.forEach(b => b.remove());
    this.bars.clear();
    this.enemyLayer.innerHTML = '';
    this.damageLayer.innerHTML = '';
    this.el('combo-wrap').classList.remove('show');
    this.hideBoss();
    this.hideLevelUp();
    this.hidePause();
    this.hideResult();
    this.el('boss-wrap').classList.add('hidden');
    this.setCombo(0, 0);
  }
}

